'use client'

import { ROLES, isRole } from './constants'

// Session storage key (stores { token, user })
const USER_STORAGE_KEY = 'crm_user_session'

// Every list page's remembered search/filters/page lives in sessionStorage under
// `${LIST_STATE_PREFIX}<userId>:<pageKey>` (see lib/hooks/useListStatePersistence.js).
// sessionStorage outlives logout within a tab, so it is wiped on logout/login, and the
// user id in the key means one account can never read another's saved filters.
export const LIST_STATE_PREFIX = 'list-state:'

export function clearPersistedListState() {
  if (typeof window === 'undefined') return
  try {
    for (const key of Object.keys(sessionStorage)) {
      if (key.startsWith(LIST_STATE_PREFIX)) sessionStorage.removeItem(key)
    }
  } catch {}
}

// Build API URL: prefer NEXT_PUBLIC_API_BASE_URL when provided, otherwise use relative paths
function apiUrl(path) {
  const base = (typeof process !== 'undefined' && process.env.NEXT_PUBLIC_API_BASE_URL) || ''
  // if base provided, strip trailing slash and prepend base; otherwise return relative path
  if (base) {
    return `${base.replace(/\/$/, '')}${path}`
  }
  return path
}

export async function login(email, password) {
  try {
    const res = await fetch(apiUrl('/api/auth/login'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
    })

    const body = await res.json().catch(() => null)

    if (res.ok && body && body.success) {
      const { token, user } = body.data || {}
      const session = { token, user }
      if (typeof window !== 'undefined') {
        // A fresh sign-in starts with clean lists, even if the previous session never
        // went through logout() (e.g. it expired or was replaced from another tab).
        clearPersistedListState()
        localStorage.setItem(USER_STORAGE_KEY, JSON.stringify(session))
      }
      return { success: true, user }
    }

    return { success: false, error: (body && body.message) || 'Invalid credentials' }
  } catch (err) {
    // Network error - return friendly message
    return { success: false, error: 'Network error. Please try again.' }
  }
}

export async function registerOrganization(organisationInfo, userInfo) {
  try {
    const res = await fetch(apiUrl('/api/auth/registerOrganization'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ OrganisationInfo: organisationInfo, userInfo }),
    })
    const body = await res.json().catch(() => null)
    if (res.ok && body && body.success) {
      return { success: true, data: body.data, message: body.message }
    }
    return { success: false, error: (body && body.message) || 'Registration failed' }
  } catch (err) {
    return { success: false, error: 'Network error. Please try again.' }
  }
}

/**
 * Re-fetch the session from the server and replace the stored copy.
 *
 * Permissions ride in the JWT, so without this a role edit doesn't reach a
 * signed-in user until they log out and back in — sessions never expire on
 * their own, so that could be days. Returns the fresh user, or null if the
 * refresh failed (in which case the existing session is left untouched; a 401
 * is handled by the api client, which logs out).
 */
export async function refreshSession() {
  const token = getToken()
  if (!token) return null

  try {
    const res = await fetch(apiUrl('/api/auth/me'), {
      headers: { Authorization: `Bearer ${token}` },
    })
    const body = await res.json().catch(() => null)

    if (res.status === 401) {
      logout()
      return null
    }
    if (!res.ok || !body?.success || !body.data?.user) return null

    const session = { token: body.data.token || token, user: body.data.user }
    localStorage.setItem(USER_STORAGE_KEY, JSON.stringify(session))
    window.dispatchEvent(new CustomEvent('session-refresh', { detail: { user: session.user } }))
    return session.user
  } catch {
    // Offline or the API is down — keep working with the session we have.
    return null
  }
}

export function logout() {
  if (typeof window !== 'undefined') {
    localStorage.removeItem(USER_STORAGE_KEY)
    localStorage.removeItem('crm_selected_branch')
    clearPersistedListState()
    window.location.href = '/auth/login'
  }
}

export function getCurrentUser() {
  if (typeof window === 'undefined') return null

  const sessionJson = localStorage.getItem(USER_STORAGE_KEY)
  if (!sessionJson) return null

  try {
    const session = JSON.parse(sessionJson)
    return session?.user || null
  } catch {
    return null
  }
}

// Merge fields into the stored session's user (e.g. freshly saved preferences)
// and tell listeners, without a round trip to the server.
export function updateSessionUser(patch) {
  if (typeof window === 'undefined') return
  try {
    const session = JSON.parse(localStorage.getItem(USER_STORAGE_KEY) || 'null')
    if (!session?.user) return
    session.user = { ...session.user, ...patch }
    localStorage.setItem(USER_STORAGE_KEY, JSON.stringify(session))
    window.dispatchEvent(new CustomEvent('session-refresh', { detail: { user: session.user } }))
  } catch {}
}

export function getToken() {
  if (typeof window === 'undefined') return null
  const sessionJson = localStorage.getItem(USER_STORAGE_KEY)
  if (!sessionJson) return null
  try {
    const session = JSON.parse(sessionJson)
    return session?.token || null
  } catch {
    return null
  }
}

export function isAuthenticated() {
  return getCurrentUser() !== null
}

export function getUserRole() {
  const user = getCurrentUser()
  return user?.role || null
}

// isSuperAdmin / isAdmin / isStaff live in lib/permissions.js only. They used
// to be defined here as well, with identical semantics, and consumers imported
// from whichever module they happened to reach for — so a fix applied to one
// copy silently missed the other. Import them from '@/lib/permissions'.

export function getCurrentUserId() {
  const user = getCurrentUser()
  return user?._id || user?.id || user?.userId || null
}

export function getUserBranch() {
  const user = getCurrentUser()
  return user?.branchId || null
}

export function getUserBranchName() {
  const user = getCurrentUser()
  return user?.branchName || null
}

// Normalized list of locations a non-superadmin user is assigned to.
// Backend may return `locationID` as an array of ids or populated
// {_id, name} objects; falls back to the single legacy branchId/branchName
// pair when locationID isn't present.
export function getUserLocations(user = getCurrentUser()) {
  if (!user) return []

  if (Array.isArray(user.locationID) && user.locationID.length > 0) {
    return user.locationID.map((loc) =>
      typeof loc === 'string' ? { _id: loc, name: null } : { _id: loc._id, name: loc.name || null }
    )
  }

  if (user.branchId) {
    return [{ _id: user.branchId, name: user.branchName || null }]
  }

  return []
}

// For Super Admin - get/set selected branch
export function getSelectedBranch() {
  if (typeof window === 'undefined') return null
  return localStorage.getItem('crm_selected_branch')
}

// `silent` persists the value without announcing a switch — used when syncing
// the already-effective default on first load, which must not trigger the
// branch-change listeners (e.g. the full-page reload wired up in MainLayout).
export function setSelectedBranch(branchId, { silent = false } = {}) {
  if (typeof window === 'undefined') return
  if (branchId) {
    localStorage.setItem('crm_selected_branch', branchId)
  } else {
    localStorage.removeItem('crm_selected_branch')
  }
  if (silent) return
  window.dispatchEvent(
    new CustomEvent('branch-change', {
      detail: { branchId },
    })
  )
}

// Get effective branch for queries (considers selected branch for super
// admin, and the active pick for staff assigned to more than one location)
export function getEffectiveBranch() {
  const user = getCurrentUser()
  if (!user) return null

  if (isRole(user.role, ROLES.SUPER_ADMIN)) {
    return getSelectedBranch() // Can be null for "All Branches"
  }

  const locations = getUserLocations(user)
  if (locations.length > 1) {
    const selected = getSelectedBranch()
    if (selected && locations.some((loc) => loc._id === selected)) {
      return selected
    }
    return locations[0]._id
  }

  return locations[0]?._id || user.branchId || null
}

